"use client";
import type { StarterPromptGroup } from "../../lib/types";

interface Props {
  groups: StarterPromptGroup[];
  onPick: (prompt: string) => void;
  assistantName?: string;
  kind?: string;
  ready?: boolean;
}

const ICONS: Record<string, string> = {
  flow: "⇄",
  bug: "⚠",
  spec: "§",
  compare: "⇆",
};

/**
 * Empty state. The prompts are generated by the backend from the real corpus
 * (real module names, real release names), so they are guaranteed to be
 * answerable by the indexed documents.
 */
export function StarterPrompts({ groups, onPick, assistantName, kind, ready }: Props) {
  return (
    <div className="mx-auto w-full max-w-3xl space-y-6 py-6">
      <div className="text-center">
        <h1 className="text-2xl font-semibold tracking-tight text-fg">
          {assistantName ?? "AsrBrain"}
        </h1>
        <p className="mt-1.5 text-sm text-muted">
          {kind ?? "citation-grounded AUTOSAR engineering assistant"}
        </p>
        <p className="mx-auto mt-3 max-w-xl text-balance text-sm leading-relaxed text-faint">
          Ask about the indexed specification, trace a requirement to its code, or describe a
          symptom and get the checks and candidate fixes — every claim linked to a document and
          page.
        </p>
        {ready === false && (
          <p className="mt-3 inline-block rounded-lg border border-warn/40 bg-warn/10 px-3 py-1.5 text-xs text-warn">
            The corpus is not available. Ingest documents before asking questions.
          </p>
        )}
      </div>

      <div className="grid gap-4 sm:grid-cols-2">
        {groups.map((g) => (
          <section key={g.group} className="panel-flat p-3">
            <h2 className="mb-2 flex items-center gap-1.5 text-xs font-semibold uppercase tracking-wide text-muted">
              <span className="text-accent">{ICONS[g.icon] ?? "◆"}</span>
              {g.group}
            </h2>
            <ul className="space-y-1.5">
              {g.prompts.map((p) => (
                <li key={p.title}>
                  <button
                    className="w-full rounded-lg border border-transparent px-2.5 py-2 text-left text-sm text-fg/85 transition-colors hover:border-accent/40 hover:bg-ink-800/60 hover:text-fg"
                    onClick={() => onPick(p.prompt)}
                  >
                    {p.title}
                    <span className="mt-0.5 block text-2xs leading-relaxed text-faint">{p.prompt}</span>
                  </button>
                </li>
              ))}
            </ul>
          </section>
        ))}
      </div>
    </div>
  );
}
